function r(e){return new Promise(t=>setTimeout(t,e))}async function o(e){const t=Date.now()+2e3;for(;!chrome.storage?.[e];){if(Date.now()>t)throw new Error(`chrome.storage.${e} did not become available in time`);await r(25)}return chrome.storage[e]}async function s(e,t="local"){return(await o(t)).get(e)}async function a(e,t="local"){return(await o(t)).set(e)}async function c(e,t="local"){return(await o(t)).remove(e)}export{a,c as b,s};
